// Inlines the used Phosphor icons (regular + fill) into src/ui/icons/generated.ts. No runtime icon font.
// Add a name to ICONS, run `node scripts/build-icons.mjs`, commit the generated file.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const ICONS = ['barbell', 'caret-left', 'caret-right', 'check', 'image', 'info', 'magnifying-glass', 'minus', 'plus', 'warning', 'x', 'house', 'person-simple', 'books', 'user-circle', 'export', 'plus-square', 'dots-three-vertical', 'copy', 'device-mobile', 'download-simple'];

const root = join(process.cwd(), 'node_modules/@phosphor-icons/core/assets');
const inner = (file) => {
  const svg = readFileSync(join(root, file), 'utf8');
  const m = svg.match(/<svg[^>]*>([\s\S]*)<\/svg>/);
  if (!m) throw new Error(`bad svg: ${file}`);
  return m[1].trim();
};

let out = '// GENERATED by scripts/build-icons.mjs from @phosphor-icons/core. Do not edit by hand.\n';
out += 'export const ICONS = {\n';
for (const n of ICONS) {
  out += `  '${n}': { regular: ${JSON.stringify(inner(`regular/${n}.svg`))}, fill: ${JSON.stringify(inner(`fill/${n}-fill.svg`))} },\n`;
}
out += '} as const;\nexport type IconName = keyof typeof ICONS;\n';
writeFileSync(join(process.cwd(), 'src/ui/icons/generated.ts'), out);
console.log(`build-icons: ${ICONS.length} icons written`);
